import sys


def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    M = int(input_data[1])

    col_sums = [0] * M
    idx = 2
    for _ in range(N):
        for j in range(M):
            col_sums[j] += int(input_data[idx])
            idx += 1

    print(min(col_sums))


if __name__ == "__main__":
    main()
